{
  "ok": false,
  "name": "draw_traverse",
  "error": {
    "type": "invalid_params",
    "message": "'space' is a required property",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-004' or 'P-201'"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ],
          "description": "override linetype; omit for ByLayer"
        },
        "start": {
          "description": "where the traverse begins: a point [x, y] (x = easting, y = northing), or an entity id to continue from its end (start_at says which end; the entity's direction there is the course a leading deflection turns from)"
        },
        "start_at": {
          "type": "string",
          "enum": [
            "start",
            "end"
          ],
          "description": "with a start entity: continue from its end (default) or its start"
        },
        "legs": {
          "type": "array",
          "items": {
            "type": [
              "object",
              "string"
            ],
            "description": "one course. Straight: a direction (exactly one of bearing, azimuth, deflection, angle_right) and distance. Curve: radius, turn and one of delta, length or chord; it continues the previous course's direction unless chord_bearing places it (a non-tangent curve). Or the course as text: \"N 47°30'15\\\" E 250\", \"AZ 75.5 250\", \"33 L 820\", \"CURVE R=450 LEFT DELTA=33\"",
            "properties": {
              "bearing": {
                "type": "string",
                "description": "quadrant bearing: N 47°30'15\" E, S47-30-15W, N47E"
              },
              "azimuth": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "degrees clockwise from north, 0-360 (a number or DMS text)"
              },
              "deflection": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "the angle turned from the previous course, with its side: '33 L', '18°30'00\" RT', or a number with right (clockwise) positive; or its size with turn"
              },
              "turn": {
                "type": "string",
                "enum": [
                  "left",
                  "right",
                  "L",
                  "R"
                ],
                "description": "which way a deflection or a curve turns"
              },
              "angle_right": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "angle measured clockwise from the backsight (the previous course run backwards), as a field traverse records it"
              },
              "distance": {
                "type": "number",
                "exclusiveMinimum": 0,
                "description": "length of a straight course (feet in model)"
              },
              "radius": {
                "type": "number",
                "exclusiveMinimum": 0,
                "description": "radius of a curve course -- giving one makes the course a curve"
              },
              "delta": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "a curve's central angle"
              },
              "length": {
                "type": "number",
                "exclusiveMinimum": 0,
                "description": "a curve's arc length"
              },
              "chord": {
                "type": "number",
                "exclusiveMinimum": 0,
                "description": "a curve's chord length"
              },
              "chord_bearing": {
                "type": [
                  "string",
                  "number"
                ],
                "description": "a non-tangent curve's chord bearing (or azimuth)"
              }
            },
            "additionalProperties": false
          },
          "minItems": 1,
          "description": "the courses in order, each from where the last one ended"
        },
        "initial_bearing": {
          "type": "string",
          "description": "the direction a leading deflection or tangent curve turns from, as a quadrant bearing"
        },
        "initial_azimuth": {
          "type": [
            "number",
            "string"
          ],
          "description": "the same as an azimuth"
        },
        "close": {
          "type": "boolean",
          "description": "the traverse should close on its start: report the misclosure (distance, bearing, precision 1:N) and, when drawing, add the closing course"
        },
        "polyline": {
          "type": "boolean",
          "description": "draw one polyline instead of separate lines (straight courses only; with close it is a closed polyline)"
        }
      },
      "required": [
        "space",
        "start",
        "legs"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "model",
      "start": [
        4100.0,
        7300.0
      ],
      "legs": [
        {
          "bearing": "S 76°15'00\" E",
          "distance": 650.0
        },
        {
          "deflection": "33 L",
          "distance": 820.0
        },
        "N 71°45'00\" E 540"
      ],
      "layer": "V-SURV-LINE"
    }
  },
  "warnings": []
}

